API_VERSION = 2
def encode_v2(values, *, keep_zero, layout):
    items = []
    for i, n in enumerate(values):
        if keep_zero or n != 0:
            items.append([i, n] if layout == "pairs" else {"index": i, "value": n})
    return {"version": 2, "items": items}

